class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF 9 uses ReadItem for single-partition reads by default,
        // but patch-based updates now require explicit opt-in for partial updates.
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }

    // Breaking change 5: Raw SQL queries referencing "Discriminator" must be updated
    // if you do NOT configure HasJsonPropertyName("Discriminator") (shown in BlogContext).
    // Without that config, the new property name is "$type", so queries would need:
    //   SELECT * FROM c WHERE c["$type"] = 'Blog'
    // Since we preserved the old name above, existing queries still work.
}

